// Year 2 reading to greater depth: phonics (alternative spellings), wonderful words,
// and comprehension of real texts (Beatrix Potter, Stevenson) plus original stories and
// fact files about racing, space and heroes. Questions follow the KS1 reading domains:
// vocabulary, retrieval, sequence, inference and prediction.
// Each passage ends with greater-depth items (ids ending .d1, .d2…): inference from evidence,
// prediction, the writer’s choices and links to other texts in the app.

import { readFileSync } from 'node:fs';

const PASSAGES = JSON.parse(readFileSync(new URL('./passages.json', import.meta.url), 'utf8'));
const P = (key) => ({ passage: PASSAGES[key].passage, passageSource: PASSAGES[key].passageSource });
const fact = (id, topic, prompt, answer, distractors, explain, extra = {}) => ({ id: `reading.${id}`, topic: `reading.${topic}`, kind: 'fact', prompt, answer, distractors, explain, ...extra });
const mcq = (id, topic, prompt, options, explain, extra = {}) => ({ id: `reading.${id}`, topic: `reading.${topic}`, kind: 'mcq', prompt, options: options.map(([text, correct, feedback]) => ({ text, correct: !!correct, feedback })), explain, ...extra });
const order = (id, topic, prompt, items, explain, extra = {}) => ({ id: `reading.${id}`, topic: `reading.${topic}`, kind: 'order', prompt, items, labels: null, explain, ...extra });
const choiceOnly = { formats: ['choice'] };

// --- original stories (written for this app) ---------------------------------------------
const RACE = { passage: 'The Big Race\n\nThe stadium lights blazed. Turbo, a small red racing car, rolled up to the starting line. Next to him was Blaze, the fastest car in the league, revving his engine loudly.\n\n“You’re too small to win,” Blaze laughed.\n\nTurbo said nothing. He had been practising the bendy corners every night.\n\nThe flag dropped! Blaze zoomed ahead on the long straight road. But when the track twisted like a snake, Blaze skidded wide. Turbo hugged the corners, smooth and steady.\n\nOn the last lap, Blaze’s tyres were worn out. Turbo crept past him, then pushed his engine as hard as it would go. He crossed the line first by the length of a bumper!\n\nBlaze rolled up beside Turbo, smiling for the first time. “I was wrong,” he said. “It’s not about size. It’s about practice.”', passageSource: 'A story written for this app' };
const SPACE = { passage: 'The Lost Robot\n\nCaptain Nova’s spaceship landed on a frosty purple planet. Her little robot, Bleep, beeped nervously. Bleep did not like the cold.\n\n“We need to find the crystal that powers our ship,” said Captain Nova. “Stay close.”\n\nBut Bleep spotted something shiny behind a rock and wobbled off to look. When he turned round, the captain had gone. The wind howled. Bleep’s lights flickered blue with fear.\n\nThen Bleep remembered his training. He switched on his signal beam and pointed it at the sky. Far away, Captain Nova saw a bright stripe of light.\n\nShe ran towards it and found Bleep beside a glowing green crystal: the very one they needed!\n\n“You got lost,” she said, “but you also found exactly what we were looking for.” Bleep beeped proudly all the way home.', passageSource: 'A story written for this app' };
const HERO = { passage: 'The Quiet Hero\n\nEveryone in Brickton knew about Thunderbolt. He could fly faster than a jet and lift a bus with one hand. But nobody knew about Pip.\n\nPip had no cape and no superpowers. She ran the little bakery on the corner.\n\nOne stormy evening, the power went out across the whole town. Thunderbolt zoomed off to fix the broken power station. Meanwhile, the streets grew dark and cold, and people were frightened.\n\nPip lit every candle in her bakery. She opened the doors and called, “Come in! It’s warm in here!” All night long she handed out hot bread and kind words.\n\nIn the morning, when the lights came back on, Thunderbolt landed outside the bakery. He saw the crowd of happy, sleepy people.\n\n“You’re a hero too,” he told Pip. She just smiled and offered him a bun.', passageSource: 'A story written for this app' };
const ROCKET = { passage: 'Fact file: Footprints on the Moon\n\nOn 20 July 1969, two American astronauts landed on the Moon. Soon after, they became the first people to walk on it. Their names were Neil Armstrong and Buzz Aldrin. A third astronaut, Michael Collins, stayed in the spacecraft circling above.\n\nThe journey to the Moon took about three days. The astronauts wore special spacesuits because there is no air to breathe on the Moon.\n\nWhen Neil Armstrong stepped onto the dusty ground, he said, “That’s one small step for man, one giant leap for mankind.”\n\nThere is no wind on the Moon, so the astronauts’ footprints are probably still there today!', passageSource: 'A fact file written for this app' };
const CARS = { passage: 'Fact file: Racing cars\n\nRacing cars are built to go very fast. They are low to the ground and have a smooth, pointed shape so the air flows over them easily.\n\nRacing tyres are wide and have no grooves when the track is dry. This helps them grip the road. In the rain, drivers change to tyres with grooves to push the water away.\n\nDuring a race, cars drive into the pit lane for a pit stop. A team of mechanics can change all four tyres in about two seconds!\n\nDrivers wear a fireproof suit and a strong helmet to keep them safe. Some races are more than 300 kilometres long, so drivers must be very fit.', passageSource: 'A fact file written for this app' };

// fables, retold for this app (the stories are thousands of years old)
const HARE = { passage: 'The Hare and the Tortoise\n\nA hare was always boasting about how fast he could run. “Nobody can beat me,” he said.\n\nThe tortoise looked up slowly. “I will race you,” she said.\n\nThe hare laughed so hard he nearly fell over. But the race began. The hare dashed away and was soon far ahead. He was so sure he would win that he lay down under a tree for a nap.\n\nThe tortoise kept going, one slow step after another, never stopping.\n\nWhen the hare woke up, he raced to the finish line. But the tortoise was already there, waiting.\n\nSlow and steady wins the race.', passageSource: 'A fable by Aesop, retold for this app' };
const LION = { passage: 'The Lion and the Mouse\n\nA lion was sleeping in the sun when a tiny mouse ran across his nose. The lion woke up and caught the mouse in his huge paw.\n\n“Please let me go,” squeaked the mouse. “One day I might help you.”\n\nThe lion laughed. How could a little mouse ever help a mighty lion? But he let her go.\n\nA few days later, the lion was caught in a hunter’s net. He roared and roared, but he could not get free.\n\nThe mouse heard him. She ran to the net and nibbled through the ropes until the lion was free.\n\n“You laughed at me,” said the mouse, “but even a little friend can be a great help.”', passageSource: 'A fable by Aesop, retold for this app' };

const PHONICS_1 = [
  // [prompt, answer, distractors, explain]
  ['Which word has the same sound as the “ai” in rain?', 'play', ['plan', 'pal', 'tap'], '“ay” in play makes the same sound as “ai” in rain.'],
  ['Which word has the same sound as the “ay” in day?', 'cake', ['cat', 'cap', 'can'], 'a-e (a, a letter, e) in cake makes the same sound: split digraph.'],
  ['Which spelling is right?', 'train', ['trayn', 'trane', 'trein'], '“ai” usually comes in the middle of a word: train, rain, paint.'],
  ['Which spelling is right?', 'today', ['todai', 'todae', 'tadey'], '“ay” usually comes at the END of a word: day, play, today.'],
  ['Which word has the same sound as the “ee” in tree?', 'beach', ['bench', 'bed', 'bet'], '“ea” in beach makes the same sound as “ee”.'],
  ['Which word has the same sound as the “ee” in see?', 'these', ['then', 'ten', 'them'], 'e-e in these is a split digraph making the “ee” sound.'],
  ['Which spelling is right?', 'sleep', ['sleap', 'slepe', 'sleip'], 'Most “ee” words in the middle use “ee” or “ea”: you have to learn which. sleep, feet, green.'],
  ['Which word has the same sound as the “igh” in night?', 'pie', ['pin', 'pig', 'pit'], '“ie” in pie makes the same sound as “igh”.'],
  ['Which word has the same sound as the “i-e” in bike?', 'fly', ['fill', 'fit', 'fin'], 'A “y” at the end of a short word often says “igh”: fly, my, sky, cry.'],
  ['Which spelling is right?', 'light', ['lite', 'lyte', 'liet'], '“igh” is common: light, night, bright, fight.'],
];
const PHONICS_2 = [
  ['Which word has the same sound as the “oa” in boat?', 'snow', ['now', 'cow', 'how'], '“ow” can say “oa” (snow, slow) or “ow” (cow, now). Here it is snow.'],
  ['Which word has the same sound as the “o-e” in home?', 'toast', ['top', 'tot', 'tock'], '“oa” in toast and “o-e” in home make the same sound.'],
  ['Which word has the same sound as the “oo” in moon?', 'blue', ['bun', 'bug', 'bus'], '“ue” in blue makes the long “oo” sound.'],
  ['Which word has the same sound as the “ew” in new?', 'tune', ['tun', 'ten', 'tin'], 'u-e in tune makes the same sound as “ew”.'],
  ['Which word has the same sound as the “ar” in car?', 'start', ['stair', 'store', 'stir'], '“ar” as in car, star, start, park.'],
  ['Which word has the same sound as the “or” in fork?', 'saw', ['sow', 'sew', 'say'], '“aw” in saw makes the same sound as “or”.'],
  ['Which word has the same sound as the “ir” in bird?', 'turn', ['torn', 'tan', 'ten'], '“ur” in turn and “ir” in bird make the same sound. So does “er” in her.'],
  ['Which word has the same sound as the “ou” in cloud?', 'town', ['tone', 'tune', 'tin'], '“ow” in town makes the same sound as “ou” in cloud.'],
  ['Which word has the same sound as the “oi” in coin?', 'boy', ['bay', 'buy', 'bee'], '“oy” usually comes at the end (boy, toy); “oi” in the middle (coin, point).'],
  ['Which word has the same sound as the “air” in hair?', 'bear', ['beer', 'bar', 'burn'], '“ear” can say “air” (bear, wear) or “eer” (hear, ear).'],
];
const PHONICS_3 = [
  ['In “phone”, what sound do the letters “ph” make?', 'f', ['p', 'h', 'sh'], '“ph” says “f”: phone, photo, dolphin, elephant.', { accept: ['f sound', 'ff'] }],
  ['Which word starts with the same sound as “when”?', 'wet', ['hen', 'tent', 'bent'], '“wh” at the start of when, where, which sounds like “w”.'],
  ['In “city”, what sound does the “c” make?', 's', ['k', 'ch', 'sh'], 'Before e, i or y, c says “s”: city, ice, cycle. This is a soft c.', { accept: ['s sound', 'ss'] }],
  ['In “giant”, what sound does the “g” make?', 'j', ['g as in goat', 'y', 'ng'], 'Before e, i or y, g often says “j”: giant, magic, energy. This is a soft g.', choiceOnly],
  ['In “knight”, which letter is silent at the start?', 'k', ['n', 'g', 'h'], 'The k in kn- words is silent: knee, knock, knight, know.'],
  ['In “write”, which letter is silent at the start?', 'w', ['r', 'i', 't'], 'The w in wr- words is silent: write, wrong, wrap.'],
  ['What sound do the letters “-tion” make at the end of “station”?', 'shun', ['tee-on', 'tun', 'tie-on'], '-tion says “shun”: station, action, nation, motion.', choiceOnly],
  ['Which word has the same “zh” sound as “treasure”?', 'measure', ['metre', 'missed', 'master'], '“-sure” in treasure and measure makes the “zh” sound.', choiceOnly],
  ['Which spelling of the “j” sound is used at the end of “bridge”?', '-dge', ['-ge', '-j', '-gge'], 'After a short vowel, use -dge: bridge, badge, hedge. After other sounds, -ge: huge, large.', choiceOnly],
  ['How do you make the plural of “baby”?', 'babies', ['babys', 'babyes', 'babis'], 'If a word ends consonant + y, change the y to i and add -es.', choiceOnly],
];
const WORDS = [
  ['enormous', 'very, very big', 'The enormous rocket towered over the launch pad.'],
  ['tiny', 'very small', 'A tiny robot rolled under the table.'],
  ['furious', 'very angry', 'The villain was furious when his plan failed.'],
  ['delighted', 'very happy', 'Turbo was delighted to win the cup.'],
  ['exhausted', 'very tired', 'After the long race, the drivers were exhausted.'],
  ['ancient', 'very, very old', 'They explored an ancient castle.'],
  ['brave', 'not afraid to face danger', 'The brave hero ran into the storm.'],
  ['curious', 'wanting to know more', 'The curious robot pressed every button.'],
  ['peculiar', 'strange or unusual', 'There was a peculiar smell coming from the spaceship.'],
  ['gigantic', 'huge', 'A gigantic wave crashed onto the beach.'],
  ['glimpse', 'a very quick look', 'He caught a glimpse of the comet before it vanished.'],
  ['astonished', 'very surprised', 'Everyone was astonished when the tortoise won.'],
  ['gleaming', 'shining brightly', 'The gleaming trophy stood on the shelf.'],
  ['rescue', 'to save someone from danger', 'The hero flew in to rescue the kitten.'],
];

// near-synonyms: never offer one's meaning as a wrong answer for the other
const CLOSE = { enormous: ['gigantic'], gigantic: ['enormous'] };

const topics = [
  { id: 'reading.phonics-1', title: 'Same sound, different spellings: ay ai a-e, ee ea e, igh i-e y', kind: 'facts', strand: 'phonics', prereqs: [], batch: 5, intro: 'The same sound can be spelt in different ways. ay (may I play), ai (snail in the rain) and a-e (make a cake) all make the same sound. Let’s spot them!', teach: 'Explain two different ways to spell the sound in “rain”.', talk: 'Ask {him} to find three words with “ay” on a cereal box or in a book.' },
  { id: 'reading.phonics-2', title: 'Same sound, different spellings: oa ow o-e, oo ew ue, or aw, ir ur er, ou ow, oy oi', kind: 'facts', strand: 'phonics', prereqs: ['reading.phonics-1'], batch: 5, intro: 'More sounds with more than one spelling: blow the snow and goat in a boat, poo at the zoo and chew the stew, whirl and twirl and nurse for a purse.', teach: 'Explain why “ow” can be tricky (cow or snow?).', talk: 'Play “I spy” with sounds: I spy something with an “oo” sound.' },
  { id: 'reading.phonics-3', title: 'Tricky letters: ph, wh, soft c and g, silent letters', kind: 'facts', strand: 'phonics', prereqs: ['reading.phonics-2'], batch: 5, intro: 'Some letters play tricks: ph says “f”, the k in knight is silent, and c says “s” in city.', teach: 'Explain what a silent letter is, with an example.', talk: 'Find a silent letter in a word on a sign.' },
  { id: 'reading.words', title: 'Wonderful words', kind: 'facts', prereqs: [], batch: 5, intro: 'Great readers and writers use exciting words. Instead of “big”, why not “enormous” or “gigantic”?', teach: 'Use three of today’s words in a sentence about your favourite superhero.', talk: 'Ask {him} to describe dinner using one of the wonderful words.' },
  { id: 'reading.fables', title: 'Fables: stories with a lesson', kind: 'reading', prereqs: ['reading.phonics-1'], batch: 6, intro: 'Fables are very old stories, often about animals, that teach a lesson called a moral. Read each one carefully, then answer the questions.', teach: 'Explain what the moral of “The Hare and the Tortoise” is.', talk: 'Ask {him} which fable {she} liked best and what lesson it teaches.' },
  { id: 'reading.adventures', title: 'Adventure stories: racing, space and heroes', kind: 'reading', prereqs: ['reading.fables'], batch: 6, intro: 'Three adventure stories. Read each one, then answer questions about what happens, how characters feel, and why.', teach: 'Explain how Turbo felt at the start of the race and at the end.', talk: 'Ask {him} who the real hero was in “The Quiet Hero” and why.' },
  { id: 'reading.facts', title: 'Fact files', kind: 'reading', prereqs: ['reading.fables'], batch: 6, intro: 'Non-fiction gives us facts. Look for headings, numbers and key words to find answers fast.', teach: 'Explain one difference between a story and a fact file.', talk: 'Ask {him} for three facts about racing cars.' },
  { id: 'reading.potter', title: 'Peter Rabbit', kind: 'reading', prereqs: ['reading.adventures'], batch: 6, intro: 'The Tale of Peter Rabbit was written by Beatrix Potter more than 120 years ago. Some words are old-fashioned, so read slowly and use clues.', teach: 'Explain why Peter got into trouble.', talk: 'Read the story together and ask {him} to predict what happens next.' },
  { id: 'reading.poems', title: 'Poems: trains, shadows and windy nights', kind: 'reading', prereqs: ['reading.adventures'], tier: 'stretch', batch: 6, intro: 'Poems use rhythm and rhyme to make pictures in your head. Read these aloud: you can hear the train rattling!', teach: 'Explain how the train poem sounds like a train.', talk: 'Read “From a Railway Carriage” aloud together, faster and faster.' },
];

const items = [
  ...PHONICS_1.map(([p, a, d, e, x], i) => fact(`ph1.${i + 1}`, 'phonics-1', p, a, d, e, x || choiceOnly)),
  ...PHONICS_2.map(([p, a, d, e, x], i) => fact(`ph2.${i + 1}`, 'phonics-2', p, a, d, e, x || choiceOnly)),
  ...PHONICS_3.map(([p, a, d, e, x], i) => fact(`ph3.${i + 1}`, 'phonics-3', p, a, d, e, x || {})),
  ...WORDS.map(([w, def, eg], i) => fact(`w.${w}`, 'words', `What does “${w}” mean?`, def, WORDS.filter((x) => x[0] !== w && !(CLOSE[w] || []).includes(x[0])).filter((_, k) => (k + i) % 4 === 0).slice(0, 3).map((x) => x[1]), `${w}: ${def}. “${eg}”`, { formats: ['choice'], learn: `**${w}** means ${def}.\n_${eg}_` })),

  // --- fables
  fact('hare.1', 'fables', 'Why did the hare stop during the race?', 'he was sure he would win', ['he hurt his foot on a stone', 'he got lost in the woods', 'he stopped to eat carrots'], '“He was so sure he would win that he lay down under a tree for a nap.”', { ...HARE, formats: ['choice'] }),
  mcq('hare.2', 'fables', 'What word best describes the hare at the start?', [['boastful', true], ['nervous', false, 'He says “Nobody can beat me.” That is not nervous!'], ['friendly', false, 'He laughs at the tortoise, which is not friendly.']], 'He was “always boasting”: showing off about how fast he was.', HARE),
  mcq('hare.3', 'fables', 'How did the tortoise win?', [['She kept going and never stopped', true], ['She ran faster than the hare', false, 'The tortoise is slow. She won because she never stopped.'], ['She took a short cut', false, 'There was no short cut. She just kept going.']], '“The tortoise kept going, one slow step after another, never stopping.”', HARE),
  mcq('hare.4', 'fables', 'What is the moral (the lesson) of this fable?', [['Slow and steady wins the race', true], ['Always run as fast as you can', false, 'The fast hare lost!'], ['Never race a tortoise', false, 'The lesson is about how we try, not about tortoises.']], 'Keeping going steadily beats being fast but careless.', HARE),
  order('hare.5', 'fables', 'Put these events in order.', ['The hare boasts', 'The race begins', 'The hare takes a nap', 'The tortoise wins'], 'Boast, race, nap, the tortoise wins.', HARE),
  mcq('hare.d1', 'fables', 'The hare “laughed so hard he nearly fell over.” What did he think of the tortoise’s idea?', [['He thought she could never win', true], ['He was scared she might beat him', false, 'He wasn’t scared: he was so sure he would win that he took a nap!'], ['He was glad to have a friend to race', false, 'He laughs AT her. He thinks racing a tortoise is silly.']], 'He was sure he was far too fast for her. That is why he took a nap later!', HARE),
  mcq('hare.d2', 'fables', 'Which word best describes the tortoise?', [['steady', true], ['boastful', false, 'The hare was the boastful one. The tortoise just said “I will race you.”'], ['sleepy', false, 'The hare was the one who lay down for a nap.']], '“The tortoise kept going, one slow step after another, never stopping.” Slow and steady!', HARE),
  mcq('hare.d3', 'fables', 'How do you think the hare felt when he reached the finish line?', [['Shocked that he had lost', true], ['Proud that he had won', false, 'He did not win: the tortoise “was already there, waiting.”'], ['Pleased he had a long rest', false, 'His nap cost him the race. He woke up and “raced to the finish line” in a hurry.']], 'He had been so sure he would win, but the tortoise was already there, waiting.', HARE),
  fact('lion.1', 'fables', 'What woke the lion up?', 'a mouse ran across his nose', ['a hunter shouted at him', 'rain fell on his face', 'a bird sang in a tree'], '“A tiny mouse ran across his nose.”', { ...LION, formats: ['choice'] }),
  mcq('lion.2', 'fables', 'Why did the lion laugh at the mouse?', [['He thought a mouse was too small to help', true], ['The mouse told him a very funny joke', false, 'The mouse was serious: “One day I might help you.”'], ['The mouse was wearing a tiny red hat', false, 'There is no hat in the story.']], '“How could a little mouse ever help a mighty lion?”', LION),
  mcq('lion.3', 'fables', 'How did the mouse help the lion?', [['She nibbled through the ropes', true], ['She roared to scare the hunter', false, 'Mice cannot roar. She used her teeth.'], ['She fetched the other lions', false, 'She did it herself.']], '“She ran to the net and nibbled through the ropes until the lion was free.”', LION),
  mcq('lion.4', 'fables', 'What lesson does this fable teach?', [['Even a little friend can be a great help', true], ['Lions are the strongest animals of all', false, 'The lesson is about kindness and friends of every size.'], ['It is best to sleep in the shade', false, 'That is not the lesson!']], 'Never judge someone by their size: kindness can come back to you.', LION),
  fact('lion.5', 'fables', 'Find a word in the story that means “very strong and powerful”.', 'mighty', ['tiny', 'huge', 'free'], '“a mighty lion”.', LION),
  mcq('lion.d1', 'fables', 'Which sentence shows that the mouse was brave?', [['She ran to the net and nibbled through the ropes.', true], ['“Please let me go,” squeaked the mouse.', false, 'Squeaking “please” shows she was frightened then. Look for when she went towards danger.'], ['The lion woke up and caught the mouse in his huge paw.', false, 'That sentence is about the lion, not about the mouse being brave.']], 'The lion was roaring in a hunter’s net, but the tiny mouse ran straight to him to help.', LION),
  mcq('lion.d2', 'fables', 'Think about “The Hare and the Tortoise”. How is it like “The Lion and the Mouse”?', [['The one who is laughed at proves them wrong', true], ['Both stories end with a race to the finish line', false, 'Only the hare and the tortoise have a race. The mouse saves the lion from a net.'], ['In both stories, a hunter catches the big animal', false, 'Only the lion is caught in a net. Nobody catches the hare.']], 'The hare laughs at the slow tortoise, and the lion laughs at the little mouse. Both are proved wrong.', LION),
  mcq('lion.d3', 'fables', 'The writer calls the lion “mighty” and the mouse “little”. Why?', [['So the mouse’s help is a big surprise', true], ['Because the lion is really very old', false, '“Mighty” means strong and powerful, not old.'], ['To show the mouse is only a baby', false, '“Little” is about her size. Nothing says she is a baby.']], 'The smallest animal saves the strongest one. Making them so different makes the lesson stronger.', LION),
  mcq('lion.d4', 'fables', 'Which words near the start give a clue about how the story will end?', [['“One day I might help you.”', true], ['“The lion laughed.”', false, 'That tells us what the lion thought then. It doesn’t hint at the ending.'], ['“A lion was sleeping in the sun.”', false, 'That just sets the scene.']], 'The mouse’s promise comes true when she nibbles through the net. Good readers spot clues like this and use them to predict.', LION),

  // --- adventures
  mcq('race.1', 'adventures', 'What did Blaze say to Turbo before the race?', [['“You’re too small to win.”', true], ['“Good luck!”', false, 'Blaze was not kind at the start.'], ['“Let’s race together.”', false, 'Look at what Blaze laughed.']], 'Blaze laughed: “You’re too small to win.”', RACE),
  mcq('race.2', 'adventures', 'Why did Turbo say nothing?', [['He was calm and knew he had practised', true], ['He could not hear what Blaze said', false, 'The next sentence explains: he had been practising every night.'], ['He was too scared to say anything', false, 'He wasn’t scared: he had been practising every night.']], 'The writer tells us straight after: “He had been practising the bendy corners every night.”', RACE),
  fact('race.3', 'adventures', 'The track “twisted like a snake”. What does this tell you about the track?', 'it was very bendy', ['it was very long', 'it was dangerous because of snakes', 'it was straight'], 'Comparing the track to a snake shows it had lots of bends. This is called a simile.', { ...RACE, formats: ['choice'] }),
  mcq('race.4', 'adventures', 'Why did Turbo win?', [['He was good at the corners', true], ['He was the biggest car in the race', false, 'Turbo was small!'], ['Blaze stopped for a snack', false, 'Blaze’s tyres wore out; he did not stop.']], 'Practice on the corners, and pushing hard at the end.', RACE),
  mcq('race.5', 'adventures', 'How did Blaze change by the end?', [['He was kind and said he was wrong', true], ['He was angrier than ever before', false, '“Blaze rolled up beside Turbo, smiling for the first time.”'], ['He said he would stop racing', false, 'Nothing says he stopped.']], '“I was wrong. It’s not about size. It’s about practice.”', RACE),
  mcq('race.d1', 'adventures', '“He crossed the line first by the length of a bumper!” Why does this sentence end with an exclamation mark?', [['To show how exciting the finish was', true], ['Because Turbo is shouting very loudly', false, 'Nobody is speaking in this sentence. The ! shows the writer’s excitement.'], ['To show the sentence is a question', false, 'A question ends with a question mark (?).']], 'An exclamation mark can show excitement or surprise. Turbo only just won!', RACE),
  mcq('race.d2', 'adventures', 'Blaze laughs that Turbo is too small to win, then loses. Which other story is most like “The Big Race”?', [['The Hare and the Tortoise', true], ['The Lion and the Mouse', false, 'The lion laughs at the mouse, but there is no race. Who boasts, races and loses?'], ['The Lost Robot', false, 'Bleep gets lost and finds a crystal. Nobody boasts or races.']], 'The boastful hare and Blaze both lose to someone they laughed at.', RACE),
  mcq('space.1', 'adventures', 'Why did Bleep get lost?', [['He went off to look at something shiny', true], ['A big storm blew him far away', false, 'The wind howled, but he got lost by wandering off.'], ['Captain Nova left him behind on purpose', false, 'She told him to stay close.']], '“Bleep spotted something shiny behind a rock and wobbled off to look.”', SPACE),
  fact('space.2', 'adventures', 'What does “Bleep’s lights flickered blue with fear” tell you?', 'Bleep was frightened', ['Bleep was happy', 'Bleep’s battery was full', 'Bleep was hungry'], 'His lights show how he feels: blue with fear.', { ...SPACE, formats: ['choice'] }),
  mcq('space.3', 'adventures', 'How did Bleep help Captain Nova find him?', [['He shone his signal beam into the sky', true], ['He shouted as loudly as he could', false, 'He used his signal beam.'], ['He flew all the way back to the ship', false, 'He stayed and sent a signal.']], '“He switched on his signal beam and pointed it at the sky.”', SPACE),
  mcq('space.4', 'adventures', 'Why did Captain Nova say “you also found exactly what we were looking for”?', [['Bleep was next to the crystal they needed', true], ['Bleep had found her lost space helmet', false, 'It was the crystal that powers the ship.'], ['Bleep had found a brand new planet', false, 'They were already on the planet.']], 'The shiny thing was the glowing green crystal.', SPACE),
  mcq('space.d1', 'adventures', 'Bleep “beeped proudly all the way home”. Why was he proud?', [['He had found the crystal they needed', true], ['He had never got lost at all', false, 'He did get lost: “the captain had gone.” He was proud of what he found.'], ['He had won a race against the captain', false, 'There was no race. Captain Nova said he “found exactly what we were looking for”.']], 'He got lost, but he used his signal beam, and he found the glowing green crystal.', SPACE),
  mcq('space.d2', 'adventures', 'Which sentence shows that Bleep was clever as well as scared?', [['Then Bleep remembered his training.', true], ['Bleep did not like the cold.', false, 'That tells us what he dislikes, not that he was clever.'], ['Bleep’s lights flickered blue with fear.', false, 'That shows he was scared, but not that he was clever.']], 'Even though he was frightened, he remembered what to do and switched on his signal beam.', SPACE),
  mcq('space.d3', 'adventures', 'Bleep’s training helped him. In which other story does practice help a character?', [['The Big Race', true], ['The Quiet Hero', false, 'Pip is kind and brave, but the story doesn’t say she practised.'], ['The Hare and the Tortoise', false, 'The tortoise kept going, but nobody practised. The hare took a nap!']], 'Turbo “had been practising the bendy corners every night”, and it helped him win.', SPACE),
  mcq('hero.1', 'adventures', 'What was different about Pip compared with Thunderbolt?', [['She had no cape and no superpowers', true], ['She could fly faster', false, 'Thunderbolt was the one who could fly.'], ['She lived on another planet', false, 'She ran the bakery in Brickton.']], '“Pip had no cape and no superpowers. She ran the little bakery on the corner.”', HERO),
  mcq('hero.2', 'adventures', 'How did Pip help the town?', [['She opened her bakery to everyone', true], ['She fixed the broken power station', false, 'Thunderbolt did that.'], ['She called Thunderbolt for help', false, 'She helped by opening her bakery.']], '“All night long she handed out hot bread and kind words.”', HERO),
  mcq('hero.3', 'adventures', 'What is the big idea of this story?', [['You don’t need superpowers to be a hero', true], ['Bakeries are the best shops in town', false, 'The story is about kindness, not shops.'], ['Storms are more dangerous than villains', false, 'The storm is just the problem in the story.']], 'Kindness and courage make a hero.', HERO),
  fact('hero.4', 'adventures', 'Find and copy the word that tells you how the people felt in the morning.', 'happy', ['frightened', 'stormy', 'dark'], '“He saw the crowd of happy, sleepy people.” (Sleepy is right too!)', { ...HERO, accept: ['sleepy', 'happy, sleepy'] }),
  mcq('hero.d1', 'adventures', 'Thunderbolt says, “You’re a hero too.” Pip “just smiled and offered him a bun.” What does this show about Pip?', [['She is modest and kind', true], ['She wants to sell him some bread', false, 'She “offered” him a bun as a gift, just as she gave out bread all night.'], ['She is cross that he was late', false, 'She smiles. Nothing shows that she is cross.']], 'She doesn’t make a fuss about being a hero. She just keeps on being kind.', HERO),
  mcq('hero.d2', 'adventures', 'Everyone knew about Thunderbolt, but “nobody knew about Pip.” Why do you think nobody knew about her?', [['She had no cape or superpowers', true], ['She had only just moved to Brickton', false, 'Nothing says she was new: she already ran the bakery on the corner.'], ['She always hid inside her bakery', false, 'She wasn’t hiding. People notice flying and lifting buses more than kindness.']], 'Thunderbolt does amazing things everyone can see. Pip is an ordinary baker, until the storm.', HERO),
  mcq('hero.d3', 'adventures', 'Pip has no superpowers, yet she helps a whole town. Which other story shows that someone who seems weak can be a great help?', [['The Lion and the Mouse', true], ['The Big Race', false, 'Turbo wins a race, but he doesn’t help anyone in trouble.'], ['The Hare and the Tortoise', false, 'The tortoise wins a race, but she doesn’t help anyone.']], '“Even a little friend can be a great help.” Pip and the mouse both prove it.', HERO),

  // --- fact files
  fact('moon.1', 'facts', 'In which year did people first walk on the Moon?', '1969', ['1996', '1869', '2009'], '“On 20 July 1969.”', ROCKET),
  fact('moon.2', 'facts', 'Who was the first person to step onto the Moon?', 'Neil Armstrong', ['Buzz Aldrin', 'Michael Collins', 'Captain Nova'], 'Neil Armstrong stepped out first; Buzz Aldrin followed.', { ...ROCKET, accept: ['armstrong'] }),
  mcq('moon.3', 'facts', 'Why did the astronauts need spacesuits?', [['There is no air to breathe on the Moon', true], ['To look smart in their photographs', false, 'The fact file gives the reason: no air.'], ['Because it rains a lot on the Moon', false, 'The Moon is dry and dusty.']], '“They wore special spacesuits because there is no air to breathe on the Moon.”', ROCKET),
  mcq('moon.4', 'facts', 'Why are the footprints probably still there?', [['There is no wind to blow them away', true], ['Someone guards them day and night', false, 'Nobody is there.'], ['They were pressed into hard concrete', false, 'They are in dust.']], '“There is no wind on the Moon, so the astronauts’ footprints are probably still there today!”', ROCKET),
  fact('moon.5', 'facts', 'About how long did the journey to the Moon take?', 'about three days', ['about three hours', 'about three weeks', 'about three years'], '“The journey to the Moon took about three days.”', { ...ROCKET, formats: ['choice'] }),
  mcq('moon.d1', 'facts', 'Which sentence has a word that shows the writer is not completely sure?', [['The footprints are probably still there today.', true], ['On 20 July 1969, two astronauts landed on the Moon.', false, 'That is certain: it really happened on that date.'], ['Michael Collins stayed in the spacecraft.', false, 'That is a fact about what happened. Nothing shows a doubt.']], '“Probably” means very likely, but not certain. Nobody has been back to that exact spot to check!', ROCKET),
  mcq('moon.d2', 'facts', 'Neil Armstrong said, “That’s one small step for man, one giant leap for mankind.” What did he mean?', [['A small step, but huge for all people', true], ['He had jumped a very long way', false, 'He “stepped onto the dusty ground”. The giant leap is about how important the moment was.'], ['The Moon was too big to walk across', false, 'He wasn’t talking about the Moon’s size. “Mankind” means all people.']], 'One step for one man, but a giant moment for everyone: people had reached the Moon.', ROCKET),
  mcq('moon.d3', 'facts', '“The Lost Robot” is also about space. What is different about this fact file?', [['It tells us about real events', true], ['It has no people in it at all', false, 'It names three real astronauts!'], ['It is set on a purple planet', false, 'The frosty purple planet is in “The Lost Robot”. This fact file is about our real Moon.']], 'A fact file gives true information. “The Lost Robot” is a made-up story.', ROCKET),
  mcq('car.1', 'facts', 'Why are racing cars low and pointed?', [['So the air flows over them easily', true], ['So they fit into a small garage', false, 'The shape is about speed.'], ['To look scary to the other drivers', false, 'The fact file explains it is so the air flows over them easily.']], '“They are low to the ground and have a smooth, pointed shape so the air flows over them easily.”', CARS),
  mcq('car.2', 'facts', 'Why do drivers change tyres when it rains?', [['Tyres with grooves push the water away', true], ['Dry tyres would get far too heavy', false, 'The reason is grip: grooves push water away.'], ['To change the colour of the car', false, 'Colour is not mentioned.']], '“Drivers change to tyres with grooves to push the water away.”', CARS),
  fact('car.3', 'facts', 'How long can a pit stop tyre change take?', 'about two seconds', ['about two minutes', 'about twenty seconds', 'about two hours'], '“A team of mechanics can change all four tyres in about two seconds!”', { ...CARS, formats: ['choice'] }),
  fact('car.4', 'facts', 'What do drivers wear to keep safe?', 'a fireproof suit and a strong helmet', ['shorts, a T-shirt and trainers', 'a long cape and a mask', 'a spacesuit and moon boots'], '“Drivers wear a fireproof suit and a strong helmet.”', { ...CARS, formats: ['choice'] }),
  mcq('car.5', 'facts', 'How can you tell this is non-fiction, not a story?', [['It gives facts and has a fact-file heading', true], ['It has talking cars', false, 'The talking cars were in the story “The Big Race”.'], ['It starts with “Once upon a time”', false, 'It does not.']], 'Non-fiction gives true information. It often has headings and numbers.', CARS),
  mcq('car.d1', 'facts', 'A fact file should only have facts. Which sentence is an opinion, so it does NOT belong?', [['Racing is the most exciting sport in the world.', true], ['Racing tyres have no grooves when the track is dry.', false, 'That is a fact from the fact file. It can be checked.'], ['Drivers wear a fireproof suit and a strong helmet.', false, 'That is a fact from the fact file. It can be checked.']], 'An opinion is what someone thinks. Some people find other sports more exciting, so it can’t be checked.', CARS),
  mcq('car.d2', 'facts', 'How does the heading “Fact file: Racing cars” help the reader?', [['It tells you what the text is about', true], ['It tells you the name of the writer', false, 'The heading names the topic, not the writer.'], ['It tells you how the story ends', false, 'This is a fact file, not a story. The heading tells you the topic.']], 'Headings tell you what a text, or a part of it, is about, so you know what you will find.', CARS),

  // --- Peter Rabbit
  fact('pr.1', 'potter', 'Where did the rabbits live?', 'in a sand-bank under a big fir-tree', ['in a shed in Mr. McGregor’s garden', 'in a little house in the town', 'in a hole by the side of the river'], '“They lived with their Mother in a sand-bank, underneath the root of a very big fir-tree.”', { ...P('peter1'), formats: ['choice'] }),
  mcq('pr.2', 'potter', 'Why did Mrs. Rabbit tell them not to go into Mr. McGregor’s garden?', [['Their father had an accident there', true], ['The garden was closed on Sundays', false, 'She gives a sadder reason: what happened to their father.'], ['There were no vegetables left to eat', false, 'There were lots: lettuces, beans, radishes.']], '“Your Father had an accident there; he was put in a pie by Mrs. McGregor.”', P('peter1')),
  mcq('pr.3', 'potter', 'The writer says Peter was “very naughty”. What did he do?', [['He squeezed under Mr. McGregor’s gate', true], ['He picked blackberries down the lane', false, 'That was Flopsy, Mopsy and Cotton-tail, the good bunnies.'], ['He went to the baker’s on his own', false, 'Mrs. Rabbit went to the baker’s.']], 'He did exactly what his mother told him not to do.', P('peter1')),
  order('pr.4', 'potter', 'Put these in order: what Peter ate, then what he went to look for.', ['lettuces and French beans', 'radishes', 'parsley (to feel better)'], 'Lettuces and French beans, then radishes, then he went looking for parsley because he felt sick.', P('peter1')),
  mcq('pr.5', 'potter', 'Why did Peter go to look for some parsley?', [['He felt sick from eating too much', true], ['He wanted to take some home for tea', false, '“feeling rather sick, he went to look for some parsley.”'], ['Mr. McGregor told him to fetch some', false, 'He had not met Mr. McGregor yet.']], 'He had eaten too much, so he felt sick.', P('peter1')),
  mcq('pr.d1', 'potter', 'What does “he was put in a pie by Mrs. McGregor” tell you about the McGregors?', [['They are dangerous to rabbits', true], ['They are very good at baking cakes', false, 'This is not about baking for fun: the rabbits’ father was caught and eaten!'], ['They are kind to animals', false, 'Putting a rabbit in a pie is not kind!']], 'Mrs. Rabbit’s warning is serious: the garden is a dangerous place for rabbits.', P('peter1')),
  mcq('pr.d2', 'potter', '“But Peter, who was very naughty, ran straight away to Mr. McGregor’s garden.” Why does the writer start this sentence with “But”?', [['To show Peter did the opposite of the others', true], ['To show Peter went down the lane with the others', false, 'He didn’t: the others went down the lane, but Peter went to the garden.'], ['To show the story is nearly at the end', false, 'The adventure is only just starting!']], '“But” shows a contrast: the good bunnies pick blackberries, but Peter does exactly what he was told not to do.', P('peter1')),
  mcq('pr.d3', 'potter', 'Mr. McGregor is running after Peter, waving a rake and shouting “Stop thief!” Which prediction fits the clues best?', [['Peter will run away and try to hide', true], ['Peter will say sorry and help plant cabbages', false, 'Mr. McGregor is waving a rake! Peter will want to get away.'], ['Mr. McGregor will invite Peter in for tea', false, 'Remember what happened to Peter’s father. Mr. McGregor is no friend to rabbits.']], 'Peter is small, frightened and being chased, so he will run and hide. Read the next part to find out!', P('peter1')),
  mcq('pr.6', 'potter', 'Why did Peter shed big tears in the gooseberry net?', [['He thought he could not escape', true], ['He had hurt his paw on a thorn', false, '“Peter gave himself up for lost.”'], ['He missed his mother very much', false, 'He was stuck and frightened.']], '“Peter gave himself up for lost, and shed big tears.”', P('peter2')),
  fact('pr.7', 'potter', 'Find and copy the word Peter sneezed.', 'Kertyschoo', ['Atishoo', 'Stop thief', 'lippity'], '“Presently Peter sneezed—‘Kertyschoo!’” That gave away his hiding place!', { ...P('peter2'), accept: ['kertyschoo!'] }),
  mcq('pr.8', 'potter', 'Why was hiding in the can not a good idea?', [['It had lots of water in it', true], ['It was too small', false, 'It was the water that was the problem.'], ['Mr. McGregor was inside', false, 'He was looking under flower-pots.']], '“It would have been a beautiful thing to hide in, if it had not had so much water in it.”', P('peter2')),
  mcq('pr.9', 'potter', 'How did Peter escape from the tool-shed?', [['He jumped out of a small window', true], ['He dug a tunnel under the wall', false, 'He jumped out of a window.'], ['The sparrows carried him away', false, 'The sparrows only encouraged him.']], '“Peter… jumped out of a window, upsetting three plants. The window was too small for Mr. McGregor.”', P('peter2')),
  mcq('pr.10', 'potter', 'What do you predict Peter will do after he escapes?', [['Try to find his way home', true], ['Go back to eat more lettuces', false, 'He is “most dreadfully frightened”: he wants to get away!'], ['Make friends with Mr. McGregor', false, 'Mr. McGregor has been chasing him with a rake.']], 'Good predictions use clues: he is frightened and lost, so he will want to get home.', P('peter2')),
  mcq('pr.d4', 'potter', 'The sparrows “implored him to exert himself”. What were they telling Peter to do?', [['Keep trying and not give up', true], ['Stay very still and be quiet', false, 'They flew to him “in great excitement”: they wanted him to struggle free.'], ['Fly away with them', false, 'Rabbits can’t fly! They wanted him to try hard to escape.']], '“Implored” means begged, and “exert himself” means try really hard. Then Peter wriggled out just in time.', P('peter2')),
  mcq('pr.d5', 'potter', '“I think he might have got away altogether…” Who is the “I” in this sentence?', [['Beatrix Potter, telling the story', true], ['Peter Rabbit, talking about himself', false, 'Peter is “he” in this sentence, so he can’t be the “I”.'], ['Mr. McGregor, chasing Peter', false, 'Mr. McGregor wouldn’t hope that Peter got away!']], 'Sometimes the writer talks to us directly, sharing what she thinks about the story.', P('peter2')),
  mcq('pr.d6', 'potter', 'The writer tells us Peter’s jacket was “quite new”. Why might this matter?', [['Losing a new jacket is extra bad', true], ['New jackets are easy to wriggle out of', false, 'Nothing says that. The point is that he leaves a brand-new jacket behind.'], ['It means the jacket was too big for him', false, '“Quite new” is about how old it is, not its size.']], 'He loses his shoes AND a brand-new jacket, so his adventure costs him a lot.', P('peter2')),

  // --- poems (stretch)
  mcq('rw.1', 'poems', 'Who is speaking in this poem?', [['Someone on a fast train', true], ['A horse running in a field', false, 'The title tells us: “From a Railway Carriage”.'], ['A witch flying on a broomstick', false, 'The train is faster than witches!']], 'Everything flies past the window: bridges, houses, cattle, stations.', P('railway')),
  mcq('rw.2', 'poems', 'Read the first two lines aloud. Why do they sound like a train?', [['The beat is quick, like train wheels', true], ['They are slow and quiet, like a lullaby', false, 'Try reading it: it rattles along!'], ['They have no rhythm or beat at all', false, 'The beat is strong and regular, like a train.']], '“Faster than fairies, faster than witches”: the beat rattles along like train wheels.', P('railway')),
  fact('rw.3', 'poems', 'Find and copy the phrase that shows the stations go by very quickly.', 'in the wink of an eye', ['as thick as driving rain', 'lumping along with man and load', 'charging along'], '“in the wink of an eye”: as fast as blinking.', { ...P('railway'), accept: ['wink of an eye'] }),
  mcq('rw.4', 'poems', 'What does “Each a glimpse and gone for ever” mean?', [['You see each thing for a moment only', true], ['Everything on the train is lost', false, 'It is about seeing things quickly from the train.'], ['The train breaks down and stops', false, 'The train keeps going!']], 'A glimpse is a very quick look. From a fast train, you only glimpse each thing.', P('railway')),
  mcq('rw.d1', 'poems', '“Faster than fairies, faster than witches”. Why does the poet repeat the word “faster”?', [['To make you feel the train’s speed', true], ['Because he forgot he had used it', false, 'Poets choose words carefully: the repeat is on purpose.'], ['To show the train is slowing down', false, '“Faster… faster” is the opposite of slowing down!']], 'Repeating “faster” gives the line a rushing beat, like a speeding train.', P('railway')),
  mcq('rw.d2', 'poems', 'Why does the second verse keep saying “Here is… Here is… And there is…”?', [['To show sights popping up one by one', true], ['To show the traveller is pointing at a map', false, 'The speaker is looking out of a train window, not at a map.'], ['Because all the sights are in one place', false, 'They are all different: a mill, a river, a green. The train passes each in turn.']], 'Each “Here is” is a new sight flashing past the window, then gone.', P('railway')),
  mcq('sh.1', 'poems', 'What is the “little shadow” in the poem?', [['The child’s own shadow', true], ['A little brother', false, 'It goes “in and out with me” and is “very, very like me”: a shadow.'], ['A pet dog', false, 'It is the poet’s shadow.']], 'The shadow follows the child everywhere.', P('shadow')),
  mcq('sh.2', 'poems', 'What is the “funniest thing” about the shadow?', [['It grows and shrinks very fast', true], ['It can talk and sing songs', false, 'The poem says it likes to grow.'], ['It eats breakfast with the child', false, 'Shadows don’t eat!']], '“he sometimes shoots up taller like an india-rubber ball, And he sometimes gets so little that there’s none of him at all.”', P('shadow')),
  mcq('sh.3', 'poems', 'Why was the shadow “fast asleep in bed” one early morning?', [['There was no sun to make a shadow', true], ['It was ill and had to rest', false, 'It is a joke: there was no sunlight to make a shadow.'], ['It had run away to play', false, 'Shadows can’t run away. There was no sunlight to make one.']], 'Shadows need light. Before sunrise, the shadow “stayed at home”. The poet pretends it was asleep.', P('shadow')),
  mcq('sh.d1', 'poems', '“He’s a coward you can see.” Why does the child call the shadow a coward?', [['It never leaves the child’s side', true], ['It runs away from other children', false, 'It does the opposite: “He stays so close beside me.”'], ['It is scared of the child’s nurse', false, 'Nursie is only a comparison: the child would be ashamed to stick to nursie the way the shadow sticks to him.']], '“He stays so close beside me, he’s a coward you can see.” The child jokes that the shadow is scared to go anywhere alone.', P('shadow')),
  mcq('sh.d2', 'poems', 'The poet calls his shadow “he”, “lazy” and a “sleepy-head”, as if it were a person. Why?', [['To make it funny and playful', true], ['Because the shadow really can talk', false, 'Shadows can’t talk. The poet is pretending, for fun.'], ['Because it is his little brother', false, 'The shadow is “very, very like me”: it is his own shadow.']], 'Treating the shadow like a cheeky friend makes the poem funny. This is called personification.', P('shadow')),
  mcq('wn.1', 'poems', 'In “Windy Nights”, what does the child imagine on stormy nights?', [['A man galloping by on a horse', true], ['A racing car speeding past', false, 'The poem says “A man goes riding by… at the gallop”.'], ['A big ship landing on the beach', false, 'Ships are mentioned, tossed at sea, but the rider is the mystery.']], 'The noise of the wind sounds like a horse galloping.', P('windy')),
  mcq('wn.2', 'poems', 'Why do you think the child imagines a galloping rider?', [['The wind sounds like hooves', true], ['They can see a real horse outside', false, 'It is dark and late. They can only hear.'], ['They are dreaming about racing', false, 'It is the sound of the wind.']], 'Poets often turn sounds into pictures. The “gallop” matches the wind’s rhythm.', P('windy')),
  mcq('wn.d1', 'poems', 'Why does the poet repeat “By at the gallop” again and again?', [['It sounds like hooves going past', true], ['He could not think of new words', false, 'The repeat is on purpose. Read it aloud: it drums like hooves.'], ['It makes the poem calm and slow', false, 'Read it aloud: it races along like a galloping horse.']], '“By at the gallop he goes, and then / By he comes back at the gallop again.” You can hear the horse going to and fro.', P('windy')),
  mcq('wn.d2', 'poems', '“Whenever the trees are crying aloud”. What is really making the trees “cry”?', [['The strong wind in the branches', true], ['Sad birds sitting in the trees', false, 'No birds are mentioned. It is a windy night: “the wind is high”.'], ['Children crying in the house', false, 'The poem is about the stormy night outside.']], 'Trees can’t cry. The poet makes the howling wind sound like crying voices.', P('windy')),
  mcq('wn.d3', 'poems', 'How are “Windy Nights” and “From a Railway Carriage” alike?', [['Both have a fast, rushing rhythm', true], ['Both are about a trip to the seaside', false, 'One is a train ride; the other is a windy night at home.'], ['Both happen on a sunny afternoon', false, '“Windy Nights” happens “late in the night”, in the dark and wet.']], 'Read them aloud: the train rattles and the horse gallops. Both poems rush along.', P('windy')),
];

// ---------------------------------------------------------------- pictures (js/ui/visuals.js)
const TOPIC_VISUALS = {
  'reading.phonics-1': { kind: 'table', head: ['Sound', 'Ways to spell it'], rows: [['ay', 'pl**ay**, r**ai**n, c**a**k**e**'], ['ee', 'tr**ee**, b**ea**ch, h**e**'], ['igh', 'n**igh**t, p**ie**, b**i**k**e**, fl**y**']], tint: 'rows', caption: 'ay usually comes at the end of a word; ai comes in the middle.' },
  'reading.phonics-2': { kind: 'table', head: ['Sound', 'Ways to spell it'], rows: [['oa', 'b**oa**t, sn**ow**, h**o**m**e**'], ['oo', 'm**oo**n, n**ew**, bl**ue**, t**u**n**e**'], ['or', 'f**or**k, s**aw**'], ['ir', 'b**ir**d, t**ur**n, h**er**'], ['ou', 'cl**ou**d, t**ow**n'], ['oy', 'b**oy**, c**oi**n']], tint: 'rows' },
  'reading.phonics-3': { kind: 'sounds', words: ['ph.o_e.n', 'kn.igh.t', 'wr.i_e.t'], caption: 'ph says “f”. In kn and wr, the k and the w are silent: kn says “n” and wr says “r”.' },
  'reading.words': [
    { kind: 'flow', across: true, steps: ['tiny', 'small', 'big', 'enormous'], caption: 'Size words, from smallest to biggest.' },
    { kind: 'flow', across: true, steps: ['cross', 'angry', 'furious'], caption: 'Angry words, from a little bit angry to very angry.' },
  ],
};
const ITEM_VISUALS = {
  'reading.ph3.1': { kind: 'sounds', words: ['ph.o_e.n'], caption: 'ph says “f”.' },
  'reading.ph3.5': { kind: 'sounds', words: ['kn.igh.t'], caption: 'kn says “n”: the k is silent.' },
  'reading.ph3.6': { kind: 'sounds', words: ['wr.i_e.t'], caption: 'wr says “r”: the w is silent.' },
};
for (const [id, v] of Object.entries(TOPIC_VISUALS)) { const t = topics.find((x) => x.id === id); if (!t) throw new Error(`picture for unknown topic ${id}`); t.visual = v; }
for (const [id, v] of Object.entries(ITEM_VISUALS)) { const it = items.find((x) => x.id === id); if (!it) throw new Error(`picture for unknown item ${id}`); it.visual = v; }

export default [{ subject: 'reading', deck: 'core', topics, items }];
